<script lang="ts">import {onMount} from 'svelte'; import {createApiClient} from '$lib/api/client'; let summary=$state<Record<string,number>|null>(null); let error=$state(''); let confirm=$state(''); onMount(async()=>{try{summary=(await createApiClient().get<{summary:Record<string,number>}>('/api/v1/admin/reset')).summary;}catch(e){error=e instanceof Error?e.message:'Could not load reset preview';}}); async function reset(){if(confirm!=='RESET BETRAYAL GAME'){error='Type RESET BETRAYAL GAME exactly';return;} try{await createApiClient().post('/api/v1/admin/reset',{headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm,understand:true})});}catch(e){error=e instanceof Error?e.message:'Reset failed';}}</script>
<svelte:head><title>Reset | Betrayal Admin</title></svelte:head><main class="min-h-screen bg-slate-950 p-6 text-slate-100"><div class="mx-auto max-w-3xl"><h1 class="text-3xl font-semibold">Reset game</h1><p class="mt-3 text-red-300">Destructive operation. Production remains enabled and server confirmation is authoritative.</p>{#if summary}<pre class="mt-6 border border-slate-700 p-4">{JSON.stringify(summary,null,2)}</pre>{/if}<label class="mt-6 block">Type RESET BETRAYAL GAME<input class="mt-2 block w-full bg-slate-900 p-3" bind:value={confirm}/></label><button class="mt-4 border border-red-500 px-4 py-2" onclick={reset}>Execute reset</button>{#if error}<p role="alert" class="mt-4 text-red-300">{error}</p>{/if}</div></main>
